```python
import torch
from torch._dynamo.eval_frame import _debug_get_cache_entry_list

def mycompiler(gm: torch.fx.GraphModule, example_inputs):
    return torch.jit.trace(gm.forward, example_inputs)

def pre_break_graph(model, inputs):
    if torch.sum(inputs[0])>1:
        return inputs

def after_break_graph(model, inputs, outputs):
    if torch.sum(outputs[0])>1:
        return outputs

class Sub1(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.linear = torch.nn.Linear(10, 10)
        # self.register_forward_pre_hook(pre_break_graph)
        # self.register_forward_hook(after_break_graph)


    def forward(self, x):
        x = x+1
        return self.linear(x)

class Sub2(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.linear = torch.nn.Linear(10, 10)
        # self.register_forward_pre_hook(pre_break_graph)
        # self.register_forward_hook(after_break_graph)

    def forward(self, x):
        x = x+2
        return self.linear(x)

class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.sub1 = Sub1()
        self.sub2 = Sub2()

    def forward(self, x):
        x = self.sub1(x)
        x = x + 100
        x = self.sub2(x)
        return x



if __name__=="__main__":
    m = Model()
    for name, sub in m._modules.items():
        if name == "":
            continue
        opt_sub = torch.compile(sub, backend=mycompiler)
        m.register_module(name, opt_sub)

    opt_m = torch.compile(m, backend="inductor")
    res = opt_m(torch.ones(10, 10))
    print(opt_m.forward)
```
